 static void Cluster(Transform parent,float x,float z,int seed,int length){var root=G(parent,"Weathered barricade remnant "+seed,new Vector3(x,0,z));var rng=new System.Random(seed);for(int row=0;row<3;row++)for(int i=0;i<length-row;i++){if(row==2&&i%3==1)continue;var at=new Vector3(x+i*.61f+row*.24f,.12f+row*.19f,z+((float)rng.NextDouble()-.5f)*.18f);Bag(root,at,seed*37+row*10+i,row==0&&i%4==1);}Bag(root,new Vector3(x-.48f,.07f,z+.46f),seed+200,true);}
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");const string path="Assets/Scenes/3D/RecoilPrototype.unity";var original=SceneManager.GetActiveScene();var s=SceneManager.GetSceneByPath(path);bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);try{
 Directory.CreateDirectory("Backups/FactoryRearGate");EditorSceneManager.SaveScene(s,"Backups/FactoryRearGate/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();serial=0;
 var w=All<RecoilPrototype>(s).Single();var all=All<Transform>(s);var oldWall=all.Single(t=>t.name=="Left perimeter wall foreground to background");var oldCap=all.Single(t=>t.name=="Left perimeter coping");wall=oldWall.GetComponent<Renderer>().sharedMaterial;cap=oldCap.GetComponent<Renderer>().sharedMaterial;steel=Mat("Old rear gate exposed steel",new Color(.15f,.18f,.17f));paint=Mat("Rear gate flaking green paint",new Color(.13f,.19f,.16f));rust=Mat("Rear gate deep rust",new Color(.22f,.11f,.06f));cloth=Mat("Years old torn sandbag fabric",new Color(.31f,.29f,.21f));soil=Mat("Sand washed from split bags",new Color(.24f,.215f,.14f));
 var routes=All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position).ToArray();var originalCollision=All<BoxCollider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.enabled+"|"+c.bounds).ToArray();var old=w.transform.Find(Marker);if(old)Object.DestroyImmediate(old.gameObject);var g=G(w.transform,Marker,Vector3.zero);float x=oldWall.position.x;var wb=oldWall.GetComponent<Renderer>().bounds;float near=-3.2f,far=3.2f;
