 foreach(var interval in new[]{new Vector2(wb.min.z,near),new Vector2(far,wb.max.z)}){float z=(interval.x+interval.y)*.5f,length=interval.y-interval.x;if(interval.y<0){float cut=-27f;B(g,"Perimeter continues behind camera",new Vector3(x,1.92f,(interval.x+cut)*.5f),new Vector3(.70f,3.84f,cut-interval.x),wall);B(g,"Foreground cutaway wall footing",new Vector3(x,.22f,(cut+interval.y)*.5f),new Vector3(.70f,.44f,interval.y-cut),wall);var hidden=B(g,"Foreground perimeter upper wall - shadow only",new Vector3(x,2.14f,(cut+interval.y)*.5f),new Vector3(.70f,3.40f,interval.y-cut),wall);hidden.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.ShadowsOnly;}else{B(g,"Continuous wall beside rear gate",new Vector3(x,1.92f,z),new Vector3(.70f,3.84f,length),wall);B(g,"Weathered wall coping",new Vector3(x,3.95f,z),new Vector3(.86f,.22f,length),cap);}}
 foreach(float z in new[]{near-.12f,far+.12f}){B(g,"Masonry rear gate pier",new Vector3(x,2.12f,z),new Vector3(1.02f,4.24f,.64f),wall);B(g,"Heavy pier cap",new Vector3(x,4.3f,z),new Vector3(1.15f,.16f,.82f),cap);for(int j=0;j<3;j++)B(g,"Old gate hinge fixing",new Vector3(x+.52f,.6f+j*1.25f,z),new Vector3(.12f,.22f,.24f),steel);}
 for(int side=0;side<2;side++){float a=side==0?near+.23f:.05f,b=side==0?-.05f:far-.23f;var leaf=G(g,"Rear iron gate leaf "+side,new Vector3(x,0,(a+b)*.5f));foreach(float z in new[]{a,b})B(leaf,"Welded gate vertical frame",new Vector3(x,1.9f,z),new Vector3(.15f,3.65f,.12f),steel);foreach(float y in new[]{.12f,1.5f,3.68f})B(leaf,"Welded gate cross rail",new Vector3(x,y,(a+b)*.5f),new Vector3(.15f,.12f,b-a),steel);B(leaf,"Old riveted lower steel sheet",new Vector3(x,.82f,(a+b)*.5f),new Vector3(.10f,1.25f,b-a-.1f),paint);for(float z=a+.18f;z<b-.08f;z+=.33f){B(leaf,"Heavy vertical iron bar",new Vector3(x,2.58f,z),new Vector3(.085f,2.1f,.085f),steel);B(leaf,"Rusted rivet",new Vector3(x-.08f,1.45f,z),new Vector3(.035f,.055f,.055f),rust,PrimitiveType.Sphere);}Rod(leaf,"Diagonal rear gate brace",new Vector3(x+.09f,.3f,a+.08f),new Vector3(x+.09f,3.52f,b-.08f),.035f,steel);for(int j=0;j<4;j++)B(leaf,"Paint loss and corrosion",new Vector3(x-.06f,.4f+j*.20f,a+.35f+j*.38f),new Vector3(.018f,.06f,.30f),rust);}
 B(g,"Old locking keeper",new Vector3(x-.14f,1.22f,0),new Vector3(.14f,.25f,.28f),steel);B(g,"Heavy old latch bar",new Vector3(x-.2f,1.32f,0),new Vector3(.08f,.09f,.55f),steel);
 // Two rows of remnants, leaving the default and rear operation planes unobstructed.
 Cluster(g,x+1.6f,-3.1f,11,5);Cluster(g,x+2.6f,3.65f,12,5);Cluster(g,27.7f,-3.3f,21,4);Cluster(g,29.2f,3.9f,22,4);Cluster(g,37.7f,-3.2f,31,5);Cluster(g,39.1f,3.7f,32,5);
 Physics2D.SyncTransforms();foreach(var t in g.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("sandbag"))){var r=t.GetComponent<Renderer>();if(r&&r.bounds.min.z<1.3f&&r.bounds.max.z> -1.3f)throw new Exception("Sandbags intrude into lane");}
 if(g.GetComponentsInChildren<Collider>().Length+g.GetComponentsInChildren<Collider2D>().Length!=0)throw new Exception("Unexpected new collision");if(!routes.SequenceEqual(All<RecoilDoor>(s).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position)))throw new Exception("Scene travel changed");if(!originalCollision.SequenceEqual(All<BoxCollider2D>(s).Select(c=>c.GetInstanceID()+"|"+c.enabled+"|"+c.bounds)))throw new Exception("Original collision changed");
 EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");Directory.CreateDirectory("output/factory-rear-gate");File.WriteAllText("output/factory-rear-gate/verification.txt","PASS rear gate at X="+x+"; original gate-height barrier retained; perimeter continues to Z="+wb.min.z+" and "+wb.max.z+"; sandbags between rear gate and offices outside walking corridor; scene travel unchanged.\n");return "Rear gate built at X="+x+"; six old sandbag remnants added between gate and offices.";
 }finally{if(opened)EditorSceneManager.CloseScene(s,true);SceneManager.SetActiveScene(original);var visual=All<Recoil3DWorld>(original).FirstOrDefault();if(visual)visual.ApplyAtmosphere();}}
